class Solution {
public:
    vector<double> averageOfLevels(TreeNode* root) {
        vector<long long> sums;
        vector<int> counts;
        dfs(root, 0, sums, counts);
        vector<double> ans;
        for (int i = 0; i < sums.size(); ++i) {
            ans.push_back(static_cast<double>(sums[i]) / counts[i]);
        }
        return ans;
    }

    void dfs(TreeNode* node, int depth, vector<long long>& sums, vector<int>& counts) {
        if (!node) return;
        if (depth == sums.size()) {
            sums.push_back(node->val);
            counts.push_back(1);
        } else {
            sums[depth] += node->val;
            counts[depth] += 1;
        }
        dfs(node->left, depth + 1, sums, counts);
        dfs(node->right, depth + 1, sums, counts);
    }
};
